import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"PhysEditWorld: A Large-Scale Dataset Toward Physics-Editable World Models","description":"","frontmatter":{"title":"PhysEditWorld: A Large-Scale Dataset Toward Physics-Editable World Models","arxiv":"2606.26694","date":"2026-06-25","authors":"Bin Hu, Yanwen Ma, Jiehui Huang, Ziliang Zhang, Haoning Wu, Ruicheng Zhang, Yaokun Li, Zijun Wang, Yuechen Zhang, Chun-Mei Tseng, Hanhui Li, Shengju Qian, Jun Zhou, Kaipeng Zhang, Xiaodan Liang, Jiaya Jia, Xiu Li","categories":"cs.CV","topics":"游戏世界模型, 可编辑物理, 数据集","outline":[2,2]},"headers":[],"relativePath":"papers/2606.26694.md","filePath":"papers/2606.26694.md","lastUpdated":null}'),l={name:"papers/2606.26694.md"};function e(r,s,m,i,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="physeditworld-a-large-scale-dataset-toward-physics-editable-world-models" tabindex="-1">PhysEditWorld: A Large-Scale Dataset Toward Physics-Editable World Models <a class="header-anchor" href="#physeditworld-a-large-scale-dataset-toward-physics-editable-world-models" aria-label="Permalink to &quot;PhysEditWorld: A Large-Scale Dataset Toward Physics-Editable World Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2606.26694" target="_blank" rel="noreferrer">2606.26694</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-06-25</td></tr><tr><td><strong>作者</strong></td><td>Bin Hu, Yanwen Ma, Jiehui Huang, Ziliang Zhang, Haoning Wu, Ruicheng Zhang, Yaokun Li, Zijun Wang, Yuechen Zhang, Chun-Mei Tseng, Hanhui Li, Shengju Qian, Jun Zhou, Kaipeng Zhang, Xiaodan Liang, Jiaya Jia, Xiu Li</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用 UE5 回放同一段场景、动作、控制器、相机策略而只改重力，造出配对的 rollout 组，把&quot;物理规则&quot;从隐式数据统计变成可标注、可条件化、可评测的显式变量。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/world-models">世界模型</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>游戏世界模型已经从视觉预测器进化成交互式生成仿真器——Genie、DIAMOND、GameNGen、GameGen-X、YUME、LingBot-World、Matrix-Game 3.0 都能合成看起来合理的 gameplay 轨迹。但它们把物理当成数据分布的隐式规律来学：能模仿一个游戏通常怎么演化，却回答不了游戏创作中最核心的一个问题——<strong>如果改一条物理规则，同一个场景应该怎么演化</strong>。</p><p>这个区别在游戏语境下不是学术趣味。开发者日常调重力尺度、跳跃行为、摩擦、阻力、风力，用它们塑造节奏、难度、手感和涌现运动。一个把物理参数与外观、gameplay 统计纠缠在一起的世界模型，可以生成视觉上无懈可击的片段，却无法当作可编辑的游戏仿真器使用。</p><p>论文把重力选作第一个可测量的切入点，理由很实际：所有引擎都支持，且它在跳跃弧线、滞空时间、下落速度、物体轨迹上产生可观测的变化。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>游戏与强化学习环境</strong>（ALE、Procgen、MineRL、CARLA）提供交互世界或人类演示，但设计目标是固定规则下的策略学习、导航、泛化。<strong>世界探索数据集</strong>（Sekai）有大规模第一人称和无人机视角视频、丰富标注和相机轨迹，但不围绕配对的物理干预组织。<strong>游戏视频生成数据集</strong>（OGameData/GameGen-X、GF-Minecraft/GameFactory、WildWorld、MultiWorld）加了动作控制、状态或多视角监督，物理规则仍固定。</p><p><strong>物理推理与视频生成 benchmark</strong> 这一支最密集：PHYRE、CLEVRER、Physion 测直觉物理与因果推理；CoPhy、ComPhy、CRIPP-VQA、ContPhy 测反事实动力学与隐藏物理属性；VBench、VBench-2.0、VideoPhy、PhyGenBench、Physics-IQ、PhysInOne、WorldScore 测物理合理性与生成保真度。这些资源很有价值，但缺的东西很具体：<strong>没有一个提供&quot;场景、交互轨迹、相机策略全部固定而重力被显式改变&quot;的配对 gameplay 片段</strong>。</p><p>论文的 Table 1 把这个缺口做成一张表：多视角、RGB-深度-法线-音频、可编辑物理、相机标注、动作/控制五列里，PhysEditWorld 是唯一五项全 ✓ 的资源。可控生成方法这一支（force prompting、PhysGen、PhysCtrl、NewtonGen、PhysChoreo）已经在做力、扭矩、力场、物理参数的条件化，但同样缺少&quot;一条规则被改、其余全部固定&quot;的交互式 rollout 作为监督或评测材料。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>出发点是一个方法论观察：要判断模型是否<strong>理解</strong>了重力，就不能只看单条视频像不像。一条低重力视频和一条正常重力视频各自看都可以很合理，模型完全可以靠外观线索（月球场景 → 慢动作）作弊。唯一严格的检验是控制变量：同一场景、同一动作、同一相机，只改重力，看输出是否随之改变，且方向和序关系正确。</p><p>这马上带来一个数据构造难题。真实视频不可能重跑一遍并改重力；用简化物理仿真器造数据又会丢掉视觉真实性和 gameplay 语义。剩下的选择是游戏引擎——UE5 既有电影级渲染，又有完整的重力/碰撞/角色控制器栈。</p><p>但直接在 UE5 里录人玩两遍也不行：人的输入不可能完全重复。关键设计因此是<strong>回放（replay）而非重录</strong>：录下一次人类交互的语义输入序列，之后把这同一段序列在不同重力配置下重新注入同一套 gameplay 栈。这就是&quot;matched replay group&quot;的由来。</p><p>一个容易忽略的坑作者也处理了：动画时序。低重力下如果仍用地球重力的动画播放速率，滞空段会显得荒谬。他们实现了 low-gravity animation tuner，按重力倍率调整腾空状态检测与动画播放速率。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>判断模型是否真的把重力当成变量，唯一可靠的办法是把其他所有变量钉死。UE5 的回放机制恰好能做到这一点：记录语义输入动作序列而不是原始设备事件，就可以在不同物理参数下把同一段&quot;意图&quot;重跑一遍。</p><p>由此产生的配对 rollout 组让物理编辑成为<strong>受控变量</strong>，跨变体的运动差异因此可以归因于被编辑的仿真参数，而不是场景内容、输入行为、角色设置或相机规格的变化。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>数据规模：12 个电影级 UE5 场景、100+ 小时人类 gameplay 交互、60M+ 渲染 rollout 帧，全部 1280×720、30 FPS，从 8 个同步相机视角渲染。场景覆盖极地科考站、室内球场、月球和火星表面、赛博朋克街区、教室、实验室、森林山谷、科考营地、保龄球馆、剧院、现代都市街道。</p><p>Pipeline 分四步，以火星车场景（<code>Map_MarsRover</code>）为例：</p><ol><li><strong>场景与输入构建</strong>。从美术做好的 UE5 关卡出发，通过编辑器插件注册可交互资产、角色设置、碰撞配置、相机锚点和回放设置。动作序列不记录原始设备事件，而是记录 UE5 Enhanced Input System 的语义 Input Action 序列（移动轴、跳跃指令、相机增量、按键状态），从而避开键盘布局、鼠标灵敏度、手柄映射这类硬件混淆因素。</li><li><strong>受控 UE5 仿真</strong>。归一化动作序列被重新注入采集时用的同一套 gameplay 栈。物理配置作为显式仿真参数施加，而关卡、控制器逻辑、输入序列、相机策略保持不变。</li><li><strong>配对回放扩展</strong>。这是核心操作，形式化为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mopen">(</span><span class="mord mathnormal">A</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span> 是场景、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span> 是归一化动作序列、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> 是角色控制器、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span> 是可编辑物理配置、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是相机策略。扩展时固定 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">A</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 只变 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span>。重力倍率取自 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0.05</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.5</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1.0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2.0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">5.0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">20.0</span><span class="mclose">}</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2583em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">⊕</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>。</li><li><strong>同步导出与标注</strong>。Movie Render Queue 输出多分支渲染流（分割 ID、8-bit 图像序列与运动矢量/世界法线、H.264 预览、16-bit 深度），运行时 logger 写出帧级与事件级 CSV。所有记录按共享 rollout ID 与帧时间轴索引。每条 rollout 由 Qwen3-VL-8B-Instruct 生成 caption，且<strong>只看采样渲染帧、不接收仿真器元数据</strong>。渲染失败、同步断裂、严重相机穿模、仿真不稳定、或出现无法归因于目标物理编辑的偏离，全部丢弃。</li></ol><p>相机系统用的是 character-centric 多相机 rig：多个 <code>UCameraComponent</code> 嵌在角色蓝图里，通过骨骼 socket 或 spring arm 挂载，因此第一人称、第三人称、侧、前、后、斜视角在走动、转身、跳跃、坠落、着陆时保持时序对齐。回放渲染时禁用相机 lag 以保证确定性帧对齐。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化很轻。数据生成写作 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mopen">(</span><span class="mord mathnormal">A</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，配对扩展就是固定除 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span> 外的全部参数。</p><p>真正需要推导的是评测指标。由于生成视频不暴露仿真器状态或真值轨迹，作者用 VGGT 反解每帧相机轨迹，取其竖直轴分量作一维下落进度信号 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span></span></span></span>，只在着陆前区段评测。对平滑后的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span></span></span></span> 做中心差分得下落轴速度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span></span></span></span>，拟合线性模型</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6984em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">a</span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span></span></span></span></span></p><p>拟合斜率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">a</span></span></span></span> 作为归一化加速度代理，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> 衡量速度曲线在多大程度上符合线性加速模式（自由落体应有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∝</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8095em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mord mathnormal">t</span></span></span></span>，故理想情况下 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> 接近 1，且 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">a</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∝</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span>）。</p><p>真正的诊断指标是<strong>组内序关系一致性</strong>：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathrm">Align</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.8374em;vertical-align:-1.516em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">∣</span><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="mord">∣</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.809em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mclose mtight">)</span><span class="mrel mtight">∈</span><span class="mord mathcal mtight" style="margin-right:0.0822em;">P</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.516em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">[</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">0</span><span class="mclose delimcenter" style="top:0em;">]</span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0822em;">P</span></span></span></span> 是同一 replay group 内的无序对集合。完全忠实于重力的模型得 1.0，随机猜为 0.5。这个设计绕开了 VGGT 轨迹的尺度不确定性——因为它只用组内的相对序关系，不用绝对数值。作者明确说明所有速度和加速度都以归一化 VGGT 单位报告，只有 replay group 内的相对比较才有意义。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>作者强调实验目的不是给生成模型排名，而是检验&quot;在配对重力 rollout 上微调能否改善模型对显式重力条件的响应&quot;。</p><p><strong>问题一：文本条件视频生成模型对重力敏感吗？</strong> 训练/评测按 replay group 划分，保证没有场景同时出现在两边：训练集 1,530 个 (scene, action, gravity) 三元组来自 9 个场景，held-out 170 个来自另外 3 个场景。对 Wan2.2-TI2V-5B 做 rank-128 LoRA（全部 attention 投影矩阵，5 epoch，AdamW，lr <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">4</span></span></span></span></span></span></span></span></span></span></span></span>，batch 8，8×H100），重力倍率作为文本 token 注入 prompt（如 <code>&quot;gravity: 0.25g&quot;</code>）。结果：zero-shot 模型在三个重力设定（0.25×/0.75×/10.0×）下加速度代理分别是 0.0002/0.0046/0.0009，几乎为零且无序，Align 只有 33.3%，平均 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> 0.066。SFT 之后加速度代理单调上升到 0.1766/0.3983/0.6214，Align 达到 100%，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> 升到 0.570。定性上，1g prompt 下 zero-shot 模型几乎不动相机、场景近乎静止，LoRA 版本生成朝月球表面的强烈自运动并带运动模糊。Kling 3.0 与 Seedance 2.0 因未开放训练代码，只出现在定性对比中。</p><p><strong>问题二：这个失败是文本条件生成特有的吗？</strong> 用一个很干净的压力测试：从楼顶边缘持续按住 W 键，重力忠实的模型应该产生离开平台后的重力相关下落运动。Matrix-Game 3.0 和 zero-shot LingBot-World 都停在平台边缘、从不进入自由落体。LingBot-World 经 PhysEditWorld LoRA 微调后生成了离开平台和随请求重力缩放的下落自运动。说明这是跨生成范式的普遍缺陷。</p><p><strong>问题三：视觉语言模型能从视频里读出重力吗？</strong> 在同一 held-out 170 条 rollout 上让 Qwen3-VL-8B-Instruct 同时预测重力类别（低/正常/高）和连续重力倍率。zero-shot 类别准确率 24.71%——<strong>低于三分类随机基线 33.3%</strong>，中位绝对百分比误差 95.00%，within-10% 命中率仅 9.48%。LoRA SFT 后（训练时对重力标签做 ±10% 抖动以抑制标签记忆）类别准确率 95.29%，中位 APE 降到 6.22%，90.59% 的预测落在真值 10% 以内。</p><p>三组实验合起来给出一个一致的结论：重力响应能力在现有模型里几乎不存在，但它是可以被这类配对数据快速教会的。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：游戏世界模型把物理学成了数据分布的隐式规律，因此无法回答&quot;改一条物理规则后场景该怎么演化&quot;。PhysEditWorld 用 UE5 的回放机制解决数据构造难题：记录语义输入动作序列，然后在不同重力配置下重跑同一段序列，产出配对 rollout 组。数据规模是 12 个电影级场景、100+ 小时交互、60M+ 帧，8 个同步视角，配 RGB/深度/法线/音频/动作/相机/引擎状态/显式重力标签。评测用 VGGT 反解的下落进度做加速度代理，只看组内序关系一致性，从而绕开尺度不确定性。Wan2.2-TI2V-5B 的 Align 从 33.3% 提到 100%，Qwen3-VL-8B 的重力分类准确率从低于随机的 24.71% 提到 95.29%。</p><p><strong>3 句话版</strong>：判断模型是否理解重力，必须把其他变量全部钉死，而 UE5 回放恰好能做到。配对 rollout 组把物理规则从隐式统计变成可条件化、可评测的显式变量。当前模型在这一维度上接近零能力，但用这类数据 LoRA 微调就能大幅改善。</p><p><strong>1 句话版</strong>：物理不该是数据里的规律，应该是可以拧的旋钮。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一环是：<strong>VGGT 反解的相机竖直轴分量确实反映了角色的下落动力学</strong>。整个定量评测——加速度代理 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">a</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>、Align——全部建立在这个信号上。</p><p>问题在于这是一个第一人称相机的姿态估计，而相机挂在角色骨骼 socket 上。如果生成视频里角色不动而背景在动（模型把下落&quot;演&quot;成了场景上移），或者相机自身抖动、渲染出现伪影导致 VGGT 姿态漂移，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span></span></span></span> 就会给出与真实物理无关的读数。作者自己承认 VGGT 轨迹带尺度不确定性，只有组内相对比较有意义——这一步处理得很好，但没有解决&quot;信号本身是否可信&quot;。</p><p>论文提供的部分证据：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span> 从 0.066 升到 0.570 说明 SFT 后速度曲线确实更接近线性加速模式，这是一个与&quot;信号有物理意义&quot;相容的观察。缺的证据是与真值的直接对照——数据集本身有引擎状态日志，完全可以在<strong>真值 rollout</strong> 上跑一遍 VGGT，检验反解的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">a</span></span></span></span> 是否与真实重力倍率成正比。论文没有报告这一步，因此 VGGT 代理的校准是空白的。这属于基于证据的推断，不是论文的声明。</p><p>另一个量级上的隐忧：Table 2 只报告了<strong>一个</strong>代表性 held-out replay group 的三个重力设定。100% 的 Align 在三个设定、三个配对上意味着 3/3 全对，这个统计量的置信区间极宽。可以推断作者选择这样报告是因为 VGGT 的可靠性筛选丢掉了大量片段（论文提到&quot;丢弃下落进度不足或着陆检测不可靠的片段&quot;），但拒绝率没有在正文给出。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不复现数据生成，只验证核心 claim：&quot;模型对重力不敏感，且这类配对数据能修好它&quot;。</p><ul><li>数据：不需要 UE5。用任意物理引擎（pybullet 或 Blender + Bullet）造 100 组配对片段——同一初始状态、同一抛物初速度、同一相机轨迹，重力取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0.25</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1.0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">4.0</span><span class="mclose">}</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span>。每组渲染成 3 秒视频。</li><li>实现：取一个开源 image-to-video 模型，先测 zero-shot，重力倍率写进 prompt；再用 60 组做 LoRA 微调，40 组留作 held-out。</li><li>测量：由于是自己造的数据，可以直接拿到真值物体轨迹。测两件事——（a）用 VGGT 或任意姿态/光流估计器算出的加速度代理与真值重力的相关性（这补上了论文缺的校准步骤）；（b）held-out 组内的 Align 指标。</li><li>判据：若 zero-shot 的 Align 接近 0.5 而微调后显著高于 0.9，支持论文核心 claim；若代理与真值重力的相关性本身就低（比如 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.5</span></span></span></span>），则说明 Align 的提升可能来自其他线索（比如模型学会了&quot;低重力 prompt → 慢镜头&quot;这种表面关联），需要换更直接的测量。</li></ul><p>这个设计的关键增量是引入真值轨迹，把 §9 里那个未被验证的假设一并检验掉。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是：<strong>SFT 后的 100% Align 可能只反映模型学会了&quot;重力 token → 运动速度&quot;这一条浅层映射，而不是学会了重力这个物理变量</strong>。</p><p>区分二者的关键在于泛化方向。如果模型真的把重力内化成物理变量，它应该在<strong>训练中未出现的重力倍率</strong>上正确插值，并且在<strong>不同类型的重力效应</strong>上一致——不只是自由落体速度，还包括跳跃弧线的形状、滞空时间、物体被撞后的抛物线、着陆时的冲击响应。如果只是学了一条速度映射，它在自由落体上会很准，在跳跃弧线和物体抛掷上则可能各说各话。</p><p>具体反例实验：（a）<strong>留出重力值</strong>。训练时只用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0.05</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.5</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2.0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">20.0</span><span class="mclose">}</span></span></span></span>，测试时问 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0.1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1.0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">5.0</span><span class="mclose">}</span></span></span></span>，看 Align 是否保持。若在未见倍率上崩溃，说明模型在做离散查表而非连续物理建模。（b）<strong>跨效应一致性</strong>。对同一 prompt 的重力值，分别测自由落体加速度、跳跃最高点高度、滞空帧数三个量，检验它们是否给出<strong>互相一致</strong>的隐含重力估计。真正理解重力的模型应该三者一致（因为它们由同一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 决定）；只学了速度映射的模型会出现自由落体正确而跳跃弧线错误的分裂。</p><p>第二个可预测的失败场景来自数据本身：12 个场景里有月球和火星表面。低重力标签与&quot;月球/火星外观&quot;在训练分布里高度共现，模型完全可能通过场景外观而非重力 token 来决定运动速度。测试办法很直接——在地球场景（教室、街道）上下 0.05g 指令，在月球场景上下 20g 指令，看模型是否服从 token 而非外观。论文的划分按 replay group 分场景，held-out 只有 3 个场景，无法排除这种混淆。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>论文自己的路线图是加更多可编辑属性（摩擦、阻力、恢复系数、风力、物体级参数），这是自然但增量的扩展。</p><p>一个非增量的重构：<strong>把&quot;物理参数条件化&quot;翻转为&quot;从视频反演物理参数并做可微一致性闭环&quot;</strong>。</p><ul><li><strong>驱动它的局限</strong>：当前范式是单向的——给定 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span> 生成视频。这要求每个新的物理属性都要重新采数据、重新微调，而属性组合空间是指数的（重力 × 摩擦 × 阻力 × 风力 …）。PhysEditWorld 的 §6 实验其实已经暗示了另一条路：Qwen3-VL 微调后能从视频里把重力倍率估到中位误差 6.22%，说明<strong>逆向映射也是可学的</strong>，而且比正向条件化更省数据。</li><li><strong>可借鉴的相邻领域工具</strong>：系统辨识（system identification）与逆图形学（inverse graphics）里的 analysis-by-synthesis 循环，以及自监督学习里的 cycle consistency。核心是把生成器和物理估计器接成一个环：生成器按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span> 生成视频，估计器从视频反推 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9579em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9579em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span><span style="top:-3.2634em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span></span></span></span></span></span></span>，用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2079em;vertical-align:-0.25em;"></span><span class="mord">∥</span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9579em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span><span style="top:-3.2634em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mord">∥</span></span></span></span> 作为额外的训练信号。</li><li><strong>第一个实验</strong>：把 PhysEditWorld SFT 后的 Wan2.2 和 SFT 后的 Qwen3-VL 接成一个环，在<strong>没有配对真值视频</strong>的重力倍率上（比如 0.3×、3×，训练集里不存在的值）做 cycle-consistency 微调，只用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9579em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9579em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span><span style="top:-3.2634em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span></span></span></span></span></span></span> 与请求 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span></span></span></span> 的一致性作为损失。测未见倍率上的 Align 和加速度代理的单调性。如果 cycle loss 能在无配对数据的情况下把未见倍率的 Align 拉起来，就说明这条路可以把数据需求从&quot;每个参数组合都要采&quot;降到&quot;少量锚点 + 一致性约束&quot;，这对指数级的属性组合空间是质变。同时这个实验顺带就是 §11 里那个&quot;离散查表还是连续建模&quot;的判别实验。</li></ul>',60)])])}const d=a(l,[["render",e]]);export{g as __pageData,d as default};
